import{_ as t}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as i,o,af as a}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const u=JSON.parse('{"title":"Kimi Code tutorial","description":"Install Kimi Code CLI with the official script, finish /login, and complete a first conversation. Then choose the VS Code extension, ACP, or the third-party API. Legacy Python kimi-cli lives only in the appendix.","frontmatter":{"title":"Kimi Code tutorial","description":"Install Kimi Code CLI with the official script, finish /login, and complete a first conversation. Then choose the VS Code extension, ACP, or the third-party API. Legacy Python kimi-cli lives only in the appendix.","domain":"product","tags":["coding-agent"],"role":"tutorial"},"headers":[],"relativePath":"products/kimi-code/kimi-code.md","filePath":"products/kimi-code/kimi-code.md","lastUpdated":1787110548000}'),s={name:"products/kimi-code/kimi-code.md"};function n(d,e,r,l,c,h){return o(),i("div",null,[...e[0]||(e[0]=[a(`<h1 id="kimi-code-tutorial" tabindex="-1">Kimi Code tutorial <a class="header-anchor" href="#kimi-code-tutorial" aria-label="Permalink to &quot;Kimi Code tutorial&quot;">​</a></h1><blockquote><p>This page gets <strong>Kimi Code</strong> installed and editing a repo. Commands and package names are copied from <a href="https://www.kimi.com/code/docs/kimi-code-cli/guides/getting-started" target="_blank" rel="noreferrer">Getting started</a> and the <a href="https://github.com/MoonshotAI/kimi-code" target="_blank" rel="noreferrer">MoonshotAI/kimi-code README</a>. Full flags: <a href="./kimi-code-cheatsheet.html">cheatsheet</a>. Family boundaries: <a href="./">learning map</a>.</p></blockquote><h2 id="goals-and-non-goals" tabindex="-1">Goals and non-goals <a class="header-anchor" href="#goals-and-non-goals" aria-label="Permalink to &quot;Goals and non-goals&quot;">​</a></h2><p><strong>Goals</strong></p><ul><li>Install the <code>kimi</code> binary with the official script or npm</li><li>Attach a Kimi Code membership or an Open Platform key via <code>/login</code></li><li>Finish one read-only survey and one confirmed small edit</li><li>Know when to use the VS Code extension, <code>kimi acp</code>, or the third-party API</li></ul><p><strong>Non-goals</strong></p><ul><li>No Kimi chat / Work / Claw tutorial</li><li>No Python <code>kimi-cli</code> as the primary install path</li><li>No invented plan prices, no &quot;the VS Code extension should just work&quot;</li></ul><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><p>Official <a href="https://www.kimi.com/code/docs/kimi-code-cli/guides/getting-started" target="_blank" rel="noreferrer">Getting started</a> and <a href="https://www.kimi.ai/help/kimi-code/cli-getting-started" target="_blank" rel="noreferrer">Help Center</a>:</p><ul><li>OS: macOS, Linux, or Windows (PowerShell)</li><li>Account: an active <strong>Kimi membership</strong>, or a callable API key</li><li>TUI: a true-color + ligature terminal (official examples: Kitty, Ghostty)</li><li>Windows: <strong>install <a href="https://gitforwindows.org/" target="_blank" rel="noreferrer">Git for Windows</a> first</strong>. The CLI uses its Git Bash as the shell. If Git Bash is not in the default path, set <code>KIMI_SHELL_PATH</code> to the absolute path of <code>bash.exe</code></li><li>npm channel extra: <strong>Node.js 22.19.0 or later</strong></li></ul><h2 id="_1-install-the-cli" tabindex="-1">1. Install the CLI <a class="header-anchor" href="#_1-install-the-cli" aria-label="Permalink to &quot;1. Install the CLI&quot;">​</a></h2><p>Two official options. The <strong>install script is recommended</strong> (no preinstalled Node.js).</p><div class="vp-code-group vp-adaptive-theme"><div class="tabs"><input type="radio" name="group-Zpm3M" id="tab-hCfCMgm" checked><label data-title="macOS / Linux" for="tab-hCfCMgm">macOS / Linux</label><input type="radio" name="group-Zpm3M" id="tab-dyKENZj"><label data-title="Windows PowerShell" for="tab-dyKENZj">Windows PowerShell</label><input type="radio" name="group-Zpm3M" id="tab-kE9y_-7"><label data-title="npm" for="tab-kE9y_-7">npm</label><input type="radio" name="group-Zpm3M" id="tab-jdb5F01"><label data-title="pnpm" for="tab-jdb5F01">pnpm</label></div><div class="blocks"><div class="language-bash vp-adaptive-theme active"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://code.kimi.com/kimi-code/install.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> bash</span></span></code></pre></div><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">irm https:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">//</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">code.kimi.com</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">kimi</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">code</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">install.ps1 </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> iex</span></span></code></pre></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @moonshot-ai/kimi-code</span></span></code></pre></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @moonshot-ai/kimi-code</span></span></code></pre></div></div></div><p>Sources: <a href="https://www.kimi.com/code/docs/kimi-code-cli/guides/getting-started" target="_blank" rel="noreferrer">Getting started</a>, <a href="https://github.com/MoonshotAI/kimi-code" target="_blank" rel="noreferrer">repo README</a>. The script downloads the latest build, verifies the checksum, and puts <code>kimi</code> on your <code>PATH</code>.</p><p>Verify:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kimi</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span></code></pre></div><p>Command not found: reopen the terminal, or <code>source ~/.bashrc</code> / <code>source ~/.zshrc</code>. Help Center also says check whether <code>~/.local/bin</code> is on <code>PATH</code>.</p><p>macOS first launch can be slow under Gatekeeper. Help Center: add the terminal app to <strong>System Settings → Privacy &amp; Security → Developer Tools</strong>.</p><p><strong>Upgrade</strong>: <code>kimi upgrade</code> (alias <code>kimi update</code>), then <code>Install update now</code>; or <code>npm install -g @moonshot-ai/kimi-code@latest</code>. What&#39;s New also mentions <code>brew upgrade kimi-code</code> for Homebrew installs. Getting Started has <strong>no</strong> <code>brew install</code> text, so this page does not invent one.</p><p><strong>Uninstall</strong>: delete the <code>kimi</code> binary after a script install; <code>npm uninstall -g @moonshot-ai/kimi-code</code> after npm.</p><blockquote><p><strong>Do not copy the old script.</strong> Some Help Center pages still show <code>curl -LsSf https://code.kimi.com/install.sh | bash</code> or <code>uv tool install --python 3.13 kimi-cli</code>. That is Python <code>kimi-cli</code>. The current official path includes <code>/kimi-code/</code>; the package is <code>@moonshot-ai/kimi-code</code>.</p></blockquote><h2 id="_2-sign-in" tabindex="-1">2. Sign in <a class="header-anchor" href="#_2-sign-in" aria-label="Permalink to &quot;2. Sign in&quot;">​</a></h2><p>Start the TUI in a project:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> your-project</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kimi</span></span></code></pre></div><p>On first launch, in the input box:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/login</span></span></code></pre></div><p>The platform picker has two options (<a href="https://www.kimi.com/code/docs/kimi-code-cli/guides/getting-started" target="_blank" rel="noreferrer">Getting started</a>):</p><table tabindex="0"><thead><tr><th>Option</th><th>Official description</th></tr></thead><tbody><tr><td><strong>Kimi Code (OAuth)</strong></td><td>Device-code flow: open the link on any device, sign in, enter the code</td></tr><tr><td><strong>Kimi Platform API key</strong></td><td>A key from <code>platform.kimi.com</code> or <code>platform.kimi.ai</code></td></tr></tbody></table><p>Without a TUI: <code>kimi login</code> (RFC 8628 device-code; verification URL and user code go to stderr).</p><p>Sign out: <code>/logout</code>.</p><p>Other providers (Anthropic / OpenAI / Google, …) require <strong>editing</strong> <code>~/.kimi-code/config.toml</code>. See <a href="https://moonshotai.github.io/kimi-code/en/configuration/providers.md" target="_blank" rel="noreferrer">Providers and models</a>.</p><blockquote><p><strong><code>export KIMI_API_KEY=…</code> does nothing.</strong> <a href="https://moonshotai.github.io/kimi-code/en/configuration/env-vars" target="_blank" rel="noreferrer">Environment variables</a>: <code>KIMI_API_KEY</code>, <code>ANTHROPIC_API_KEY</code>, and <code>OPENAI_API_KEY</code> are <strong>not</strong> read from the shell. Put them in <code>config.toml</code> under <code>[providers.&lt;name&gt;]</code> or <code>[providers.&lt;name&gt;.env]</code>. The exception is the temporary <code>KIMI_MODEL_*</code> channel.</p></blockquote><h2 id="_3-first-conversation" tabindex="-1">3. First conversation <a class="header-anchor" href="#_3-first-conversation" aria-label="Permalink to &quot;3. First conversation&quot;">​</a></h2><p>Official first prompt:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Take a look at this project&#39;s directory structure and briefly describe what each directory is for.</span></span></code></pre></div><p>Read-only tools run automatically. File writes and shell commands <strong>ask first</strong> by default.</p><p>A more concrete official example:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Add a function in src/utils that converts any string to kebab-case, and add a unit test for it.</span></span></code></pre></div><p>Project rules: run <code>/init</code> in the repo to generate <code>AGENTS.md</code> (<a href="https://www.kimi.ai/help/kimi-code/cli-getting-started" target="_blank" rel="noreferrer">Help Center</a>).</p><p>One-shot, no TUI:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kimi</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Take a look at this project&#39;s directory structure&quot;</span></span></code></pre></div><p>Resume the <strong>most recent session in this directory</strong>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kimi</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span></span></code></pre></div><p>That is the short form of <code>--continue</code> from the <a href="https://moonshotai.github.io/kimi-code/en/reference/kimi-command" target="_blank" rel="noreferrer">kimi command</a> and Getting Started. Some Help Center pages write <code>-C</code>. Trust the CLI reference.</p><p>Leave the TUI: <code>/exit</code>, <code>Ctrl-C</code> twice while idle, or <code>Ctrl-D</code> on an empty input box.</p><h2 id="_4-interaction-approvals-and-three-permission-modes" tabindex="-1">4. Interaction, approvals, and three permission modes <a class="header-anchor" href="#_4-interaction-approvals-and-three-permission-modes" aria-label="Permalink to &quot;4. Interaction, approvals, and three permission modes&quot;">​</a></h2><p>Source: <a href="https://moonshotai.github.io/kimi-code/en/guides/interaction" target="_blank" rel="noreferrer">Interaction and input</a>.</p><table tabindex="0"><thead><tr><th>Action</th><th>How</th></tr></thead><tbody><tr><td>Send</td><td><code>Enter</code></td></tr><tr><td>Newline</td><td><code>Shift-Enter</code> or <code>Ctrl-J</code></td></tr><tr><td>File mention</td><td><code>@</code> path complete</td></tr><tr><td>Slash command</td><td><code>/</code></td></tr><tr><td>Paste image / video</td><td>macOS / Linux <code>Ctrl-V</code>; Windows <code>Alt-V</code></td></tr><tr><td>Interject while streaming</td><td><code>Ctrl-S</code></td></tr><tr><td>Interrupt</td><td><code>Esc</code> or <code>Ctrl-C</code></td></tr><tr><td>Collapse tool output</td><td><code>Ctrl-O</code></td></tr><tr><td>External editor</td><td><code>Ctrl-G</code></td></tr><tr><td>Toggle Plan</td><td><code>Shift-Tab</code> or <code>/plan</code></td></tr><tr><td>Shell mode</td><td>type <code>!</code> on an empty input</td></tr></tbody></table><p>Do not mix the three modes:</p><table tabindex="0"><thead><tr><th>Mode</th><th>How</th><th>Official behavior</th></tr></thead><tbody><tr><td><strong>Plan</strong></td><td><code>Shift-Tab</code> / <code>/plan</code> / <code>kimi --plan</code></td><td>Plan first, then edit. Leaving Plan still needs confirmation; <strong>YOLO does not skip that</strong></td></tr><tr><td><strong>YOLO</strong></td><td><code>/yolo</code> / <code>kimi --yolo</code></td><td>Auto-approve ordinary tools (writes, shell). Sensitive files (<code>.env</code>, SSH keys) and leaving Plan still ask</td></tr><tr><td><strong>Auto</strong></td><td><code>/auto</code> / <code>kimi --auto</code></td><td>Every approval is automatic and the <strong>agent will not ask you questions</strong></td></tr></tbody></table><p><code>-p</code> always uses <code>auto</code> permission and cannot be combined with <code>--yolo</code> / <code>--auto</code> / <code>--plan</code>.</p><h2 id="_5-slash-commands-you-need-first" tabindex="-1">5. Slash commands you need first <a class="header-anchor" href="#_5-slash-commands-you-need-first" aria-label="Permalink to &quot;5. Slash commands you need first&quot;">​</a></h2><p>From Getting Started. Full list: <a href="https://moonshotai.github.io/kimi-code/en/reference/slash-commands" target="_blank" rel="noreferrer">slash commands</a> and the <a href="./kimi-code-cheatsheet.html">cheatsheet</a>.</p><table tabindex="0"><thead><tr><th>Command</th><th>What it does</th></tr></thead><tbody><tr><td><code>/help</code></td><td>Command and shortcut panel</td></tr><tr><td><code>/login</code> / <code>/logout</code></td><td>Sign in / clear credentials</td></tr><tr><td><code>/model</code></td><td>Switch model</td></tr><tr><td><code>/new</code></td><td>New session</td></tr><tr><td><code>/sessions</code></td><td>Resume history</td></tr><tr><td><code>/compact</code></td><td>Compress context</td></tr><tr><td><code>/fork</code></td><td>Fork a copy (you stay on the current session)</td></tr><tr><td><code>/init</code></td><td>Generate <code>AGENTS.md</code></td></tr><tr><td><code>/usage</code></td><td>Usage and quota</td></tr><tr><td><code>/yolo</code> <code>/auto</code> <code>/plan</code></td><td>Permission / plan modes</td></tr><tr><td><code>/goal</code></td><td>Drive a persistent objective across turns</td></tr><tr><td><code>/mcp-config</code></td><td>Configure MCP conversationally</td></tr></tbody></table><h2 id="_6-kimi-code-for-vs-code" tabindex="-1">6. Kimi Code for VS Code <a class="header-anchor" href="#_6-kimi-code-for-vs-code" aria-label="Permalink to &quot;6. Kimi Code for VS Code&quot;">​</a></h2><p>Official page: <a href="https://www.kimi.com/code/docs/kimi-code-for-vscode/getting-started" target="_blank" rel="noreferrer">Quick start</a>. Marketplace: <a href="https://marketplace.visualstudio.com/items?itemName=moonshot-ai.kimi-code" target="_blank" rel="noreferrer">moonshot-ai.kimi-code</a>.</p><h3 id="read-this-eligibility-banner-first" tabindex="-1">Read this eligibility banner first <a class="header-anchor" href="#read-this-eligibility-banner-first" aria-label="Permalink to &quot;Read this eligibility banner first&quot;">​</a></h3><p>Product-docs banner (translated from the official Chinese page):</p><blockquote><p>Kimi Code for VS Code currently allows <strong>new installs only for legacy Python CLI users</strong>. Existing extension users can keep using it after upgrading to the new CLI. Other TypeScript CLI users cannot install it yet.</p></blockquote><p>The Help Center says the same. <strong>Do not assume a fresh Node CLI install can add the Marketplace extension.</strong> Prefer <code>kimi acp</code> below, or run <code>kimi</code> inside the VS Code integrated terminal.</p><p>The Marketplace page (0.7.0 observed 2026-08-19) describes a newer implementation that <strong>coexists</strong> with that banner:</p><ul><li>VS Code <strong>1.100.0</strong> or later</li><li>The extension runs the <strong>Kimi Code Node SDK</strong> in the Extension Host</li><li>When the extension and the terminal app resolve the same <code>KIMI_CODE_HOME</code>, they share <code>config.toml</code>, MCP, login, and sessions</li><li><strong>Do not</strong> open the same session in both apps (cross-process locking is not guaranteed)</li></ul><p>When the two official pages disagree, <strong>eligibility follows the product-docs banner</strong>; shared home / version requirements follow the Marketplace. Do not guess which one is obsolete.</p><h3 id="install-and-sign-in-official-steps" tabindex="-1">Install and sign-in (official steps) <a class="header-anchor" href="#install-and-sign-in-official-steps" aria-label="Permalink to &quot;Install and sign-in (official steps)&quot;">​</a></h3><ol><li>Prerequisite: a Kimi membership or API key</li><li>Search the VS Code Marketplace for <strong>Kimi Code</strong>, publisher <strong>moonshot-ai</strong></li><li>If the icon is missing: reload, or run <code>Developer: Reload Window</code> (<code>Cmd+Shift+P</code> on macOS, <code>Ctrl+Shift+P</code> on Windows/Linux)</li><li>Click the Kimi icon in the Activity Bar</li><li>Auth (gear switches modes): <ul><li><strong>Kimi account</strong>: browser OAuth</li><li><strong>API key</strong>: skip login if a key is already configured</li></ul></li></ol><h3 id="typical-workflows" tabindex="-1">Typical workflows <a class="header-anchor" href="#typical-workflows" aria-label="Permalink to &quot;Typical workflows&quot;">​</a></h3><p>Four official recipes:</p><table tabindex="0"><thead><tr><th>Scene</th><th>What to do</th></tr></thead><tbody><tr><td>Read code</td><td><code>@</code> a file / folder, ask for the flow, then follow up</td></tr><tr><td>Refactor</td><td>e.g. <code>@src/feature/</code>, review the diff, approve selectively, roll back if needed</td></tr><tr><td>Debug</td><td>Paste the error or stack, mention related files, approve the fix</td></tr><tr><td>Overview</td><td>e.g. <code>@src/services/</code>, ask for a module map or architecture summary</td></tr></tbody></table><h3 id="shortcuts" tabindex="-1">Shortcuts <a class="header-anchor" href="#shortcuts" aria-label="Permalink to &quot;Shortcuts&quot;">​</a></h3><p>From the product docs (one extra setting vs Help Center):</p><table tabindex="0"><thead><tr><th>Shortcut</th><th>Action</th></tr></thead><tbody><tr><td><code>Ctrl+Shift+K</code> / <code>Cmd+Shift+K</code></td><td>Focus the Kimi input</td></tr><tr><td><code>Alt+K</code></td><td>Insert a reference to the current file</td></tr><tr><td><code>Ctrl+N</code> / <code>Cmd+N</code></td><td>New conversation (requires <code>kimi.enableNewConversationShortcut</code>; steals the default New File binding)</td></tr><tr><td><code>↑</code> / <code>↓</code></td><td>Input history</td></tr></tbody></table><p>Command Palette → <code>Kimi Code</code> opens the panel in a tab or sidebar and manages sessions.</p><h2 id="_7-other-ides-via-acp" tabindex="-1">7. Other IDEs via ACP <a class="header-anchor" href="#_7-other-ides-via-acp" aria-label="Permalink to &quot;7. Other IDEs via ACP&quot;">​</a></h2><p>There is no first-party JetBrains / Zed plugin. The CLI exposes <code>kimi acp</code>; the IDE spawns it as a JSON-RPC child. Finish <code>/login</code> in a terminal first. macOS GUI children often <strong>do not</strong> inherit your shell <code>PATH</code> — set <code>command</code> to the absolute path from <code>which kimi</code>.</p><p>Zed, in <code>~/.config/zed/settings.json</code> (<a href="https://moonshotai.github.io/kimi-code/en/guides/ides" target="_blank" rel="noreferrer">Using in IDEs</a>):</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;agent_servers&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;Kimi Code CLI&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;type&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;custom&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;command&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;kimi&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;args&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;acp&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;env&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>JetBrains (IntelliJ / PyCharm / WebStorm, …) configures ACP in AI Chat; <code>command</code> <strong>must be an absolute path</strong>. Paseo: pick the built-in provider or add <code>[&quot;kimi&quot;, &quot;acp&quot;]</code> in <code>~/.paseo/config.json</code>.</p><p>Self-check: run <code>kimi acp</code> in a terminal. If it blocks on stdin, the CLI is fine and the IDE config is wrong. An immediate error is usually a missing login.</p><h2 id="_8-use-kimi-code-from-third-party-tools" tabindex="-1">8. Use Kimi Code from third-party tools <a class="header-anchor" href="#_8-use-kimi-code-from-third-party-tools" aria-label="Permalink to &quot;8. Use Kimi Code from third-party tools&quot;">​</a></h2><p>Product hub: members can create up to <strong>5</strong> API keys in the <a href="https://www.kimi.com/code/console" target="_blank" rel="noreferrer">console</a> (<strong>shown only at creation time</strong>).</p><table tabindex="0"><thead><tr><th>Protocol</th><th>Base URL</th><th>Common endpoint</th></tr></thead><tbody><tr><td>OpenAI-compatible</td><td><code>https://api.kimi.com/coding/v1</code></td><td><code>https://api.kimi.com/coding/v1/chat/completions</code></td></tr><tr><td>Anthropic-compatible</td><td><code>https://api.kimi.com/coding/</code></td><td><code>https://api.kimi.com/coding/v1/messages</code></td></tr></tbody></table><p>Some tools want only the Base URL (the hub names Claude Code). Some want the full endpoint (the hub names Trae).</p><p>Officially named consumers: Claude Code, OpenCode, Codex, Roo Code, plus generic frameworks such as OpenClaw and Hermes (<a href="https://www.kimi.com/zh-cn/help/kimi-code/membership-guide" target="_blank" rel="noreferrer">membership-guide</a>). Per-tool env var names live in those tools&#39; docs — this page does not invent them.</p><blockquote><p>Hub original: keep the tool&#39;s real client identity. Tampering with the User-Agent is a violation and can suspend membership benefits.</p></blockquote><p>This is not the Open Platform:</p><table tabindex="0"><thead><tr><th></th><th>Kimi Code platform</th><th>Kimi Open Platform</th></tr></thead><tbody><tr><td>Base URL</td><td>table above</td><td><code>https://api.moonshot.cn/v1</code></td></tr><tr><td>Billing</td><td>membership + rate limits</td><td>pay-as-you-go</td></tr><tr><td>Fit</td><td>terminal / IDE agents</td><td>product integration</td></tr></tbody></table><p>Keys <strong>do not</strong> mix.</p><h2 id="_9-which-model" tabindex="-1">9. Which model <a class="header-anchor" href="#_9-which-model" aria-label="Permalink to &quot;9. Which model&quot;">​</a></h2><p>Trust <a href="https://www.kimi.com/code/docs/kimi-code/models" target="_blank" rel="noreferrer">Models</a> as of 2026-08-19. That page says there are <strong>3</strong> model IDs.</p><table tabindex="0"><thead><tr><th>Model ID</th><th>Model</th><th>Context</th><th>Who</th></tr></thead><tbody><tr><td><code>k3</code></td><td>Kimi K3</td><td>Moderato up to 256k; Allegretto+ up to 1M</td><td>Moderato+. Andante: not supported yet</td></tr><tr><td><code>kimi-for-coding</code></td><td>Kimi K2.7 Code</td><td>256k</td><td>All members</td></tr><tr><td><code>kimi-for-coding-highspeed</code></td><td>Same K2.7 Code, high speed</td><td>256k</td><td>Allegretto+</td></tr></tbody></table><p>Official: high-speed coding ability matches the standard ID. Product docs: output about <strong>5–6×</strong>, quota about <strong>3×</strong>. The models table says &quot;6× speed, 3× consumption.&quot; A wrong high-speed ID <strong>does not error</strong>; it falls back to <code>kimi-for-coding</code>. Insufficient plan → <strong>401</strong>.</p><p>CLI: <code>/model</code>. VS Code: the input dropdown; restart or reinstall if the target is missing. Switching models busts the cache — official advice is a <strong>new session</strong>.</p><h2 id="_10-where-data-lives-how-to-check-quota" tabindex="-1">10. Where data lives / how to check quota <a class="header-anchor" href="#_10-where-data-lives-how-to-check-quota" aria-label="Permalink to &quot;10. Where data lives / how to check quota&quot;">​</a></h2><ul><li>Default home: <code>~/.kimi-code/</code> (config, sessions, logs, update cache)</li><li>Move it: <code>KIMI_CODE_HOME</code></li><li>Do not hand-edit files under <code>sessions/</code></li><li>Usage: TUI <code>/usage</code>; web <strong>Settings → Subscription and invoices → My quota</strong>; console after Extra Usage is on</li></ul><p>Quota rules copied from <a href="https://www.kimi.com/code/docs/kimi-code/membership" target="_blank" rel="noreferrer">membership</a>: 7-day refresh, 5-hour window, devices and API keys share one pool, idle devices unbind after 30 days, monthly cap freezes Code. A new membership system will split Code from Kimi membership — amounts stay on the official pricing page.</p><h2 id="common-pitfalls" tabindex="-1">Common pitfalls <a class="header-anchor" href="#common-pitfalls" aria-label="Permalink to &quot;Common pitfalls&quot;">​</a></h2><ol><li><strong>Old install URL or package name.</strong> Current: <code>code.kimi.com/kimi-code/install.sh</code> and <code>@moonshot-ai/kimi-code</code>.</li><li><strong><code>export KIMI_API_KEY</code> as login.</strong> Write <code>config.toml</code> or use <code>/login</code>.</li><li><strong>A Coding key against <code>api.moonshot.cn</code>, or the reverse.</strong> Two account systems.</li><li><strong>YOLO and Auto as synonyms.</strong> Auto also stops questions; YOLO still asks about sensitive files and leaving Plan.</li><li><strong>Assuming the VS Code extension installs for a new Node CLI user.</strong> Product docs restrict new installs to legacy Python CLI users.</li><li><strong><code>kimi: command not found</code> inside an IDE.</strong> GUI children lack PATH — use an absolute path.</li><li><strong>Windows without Git for Windows.</strong> Official shell is Git Bash. What&#39;s New: the CLI errors before launch if Git Bash is missing.</li><li><strong>Help Center <code>-C</code> for continue.</strong> CLI reference is <code>-c</code> / <code>--continue</code>.</li></ol><h2 id="appendix-migrate-from-python-kimi-cli" tabindex="-1">Appendix: migrate from Python kimi-cli <a class="header-anchor" href="#appendix-migrate-from-python-kimi-cli" aria-label="Permalink to &quot;Appendix: migrate from Python kimi-cli&quot;">​</a></h2><p>The old line is no longer maintained. It is not the main tutorial.</p><p><a href="https://www.kimi.com/code/docs/kimi-code/whats-new" target="_blank" rel="noreferrer">What&#39;s New</a>:</p><table tabindex="0"><thead><tr><th></th><th>Old kimi-cli</th><th>New Kimi Code CLI</th></tr></thead><tbody><tr><td>Runtime</td><td>Python + uv</td><td>Node.js</td></tr><tr><td>Install</td><td><code>uv tool install</code></td><td>curl / npm in §1</td></tr><tr><td>Config</td><td><code>~/.kimi/config.toml</code></td><td><code>~/.kimi-code/config.toml</code> (<strong>incompatible</strong>)</td></tr><tr><td>UI</td><td>Basic text</td><td>Full TUI</td></tr><tr><td>Subagents</td><td>No</td><td>Built-in <code>coder</code> / <code>explore</code> / <code>plan</code></td></tr></tbody></table><p><a href="https://www.kimi.com/code/docs/kimi-code-cli/guides/migration" target="_blank" rel="noreferrer">Migration guide</a>:</p><ol><li>Install the new CLI from this page.</li><li>The first <code>kimi</code> run prompts if it finds <code>~/.kimi/</code>.</li><li>Or run <code>kimi migrate</code> any time.</li><li>Choose <strong>Config only</strong> or <strong>Config + N sessions</strong>.</li></ol><p>Migrated: <code>config.toml</code>, MCP config, input history, selected sessions.</p><p><strong>Not</strong> migrated: OAuth tokens, MCP grants, old plugins. Sign in again with <code>/login</code> and re-authorize MCP.</p><p>Migration <strong>does not delete</strong> <code>~/.kimi/</code>. It is idempotent. Imported sessions are tagged <code>[imported]</code>.</p><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li>Flags, models, Base URLs → <a href="./kimi-code-cheatsheet.html">cheatsheet</a></li><li>Official recipes → <a href="https://moonshotai.github.io/kimi-code/en/guides/use-cases" target="_blank" rel="noreferrer">use cases</a></li><li>Skills / MCP / Hooks → <a href="https://moonshotai.github.io/kimi-code/en/customization/mcp" target="_blank" rel="noreferrer">customization</a></li><li>Bugs → <a href="https://github.com/MoonshotAI/kimi-code/issues" target="_blank" rel="noreferrer">GitHub Issues</a></li></ul>`,108)])])}const b=t(s,[["render",n]]);export{u as __pageData,b as default};
